protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // HasIndex removed: throws in EF Core 9 for Cosmos DB.
    // Manage indexing via the container's indexing policy (Azure Portal/Bicep).
    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");

        // Preserve "Discriminator" property name used by existing 500K documents
        // and direct SQL queries (c.Discriminator). EF Core 9 defaults to "$type".
        entity.HasDiscriminator<string>("Discriminator");

        // Preserve compound id format "Product|123" used by existing documents.
        // EF Core 9 defaults to key-only ids (e.g. "123").
        entity.HasRootDiscriminatorInJsonId(true);
    });
}

